class ServiceProxy implements ServiceApi {      // compiler enforces equivalence
  constructor(private readonly real: ServiceApi,
              private readonly metrics: Metrics) {}
  async call(request: Request): Promise<Response> {
    const started = performance.now();
    try {
      return await this.real.call(request);      // same contract
    } finally {
      this.metrics.observe('call', performance.now() - started);
    }
  }
}

