const authInterceptor: grpc.Interceptor = (options, nextCall) =>
  new grpc.InterceptingCall(nextCall(options), {
    start(metadata, listener, next) {
      metadata.set('authorization', `Bearer ${token()}`);  // policy
      next(metadata, listener);                            // delegate
    },
  });

const server = new grpc.Server({ interceptors: [authInterceptor] });
